<?php require 'config/database.php'; session_start(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$password=$_POST['password']??'';$stmt=$conn->prepare("SELECT id,name,email,password,role FROM users WHERE email=?");$stmt->bind_param("s",$email);$stmt->execute();$res=$stmt->get_result();if($user=$res->fetch_assoc()){if(password_verify($password,$user['password'])){$_SESSION['user_id']=$user['id'];$_SESSION['name']=$user['name'];$_SESSION['email']=$user['email'];$_SESSION['role']=$user['role'];header('Location: '.($user['role']==='admin'?'admin/dashboard.php':'dashboard.php'));exit;}}$msg='Invalid email or password.';} $pageTitle='Login';include 'header.php';?><h2>Login</h2><?php if(isset($_GET['registered'])):?><div class="alert">Registration successful. Please login.</div><?php endif;?><?php if($msg):?><div class="alert error"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button class="btn" type="submit">Login</button></form><?php include 'footer.php'; ?>